<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rekap Nilai {{ $exam->title }} — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 20px;background:linear-gradient(135deg,#f4f7fb,#e8eef7)}.wrap{max-width:1200px;margin:auto}.back{display:inline-block;padding:10px 13px;border-radius:10px;background:#fffd;border:1px solid #fff;color:#23395d;text-decoration:none;font-size:12px;font-weight:800}.hero{margin:18px 0;padding:28px 30px;border-radius:22px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff;position:relative;overflow:hidden}.hero:after{content:"✦";position:absolute;right:25px;top:-45px;color:#ffffff18;font-size:165px}.hero>*{position:relative}.hero h1{margin:7px 0;font-size:28px}.hero p{margin:0;color:#e7effa}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.stat,.card{background:#fffd;border:1px solid #fff;border-radius:17px;box-shadow:0 10px 23px #23395d0d}.stat{padding:17px}.stat span{display:block;color:#64748b;font-size:12px}.stat strong{display:block;margin-top:6px;font-size:27px;color:#23395d}.card{padding:20px;overflow:auto}table{width:100%;min-width:720px;border-collapse:collapse}th,td{padding:13px 9px;text-align:left;border-bottom:1px solid #e4ecf4}th{color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.4px}.score{font-size:17px;font-weight:800;color:#23395d}.tag{display:inline-block;padding:5px 8px;border-radius:20px;background:#e8eef7;color:#365d92;font-size:11px;font-weight:800}.empty{text-align:center;color:#64748b;padding:35px!important}@media(max-width:600px){body{padding:20px 14px}.stats{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="back" href="{{ route('admin.workspace','scores')